    {
        "path": "astria-ascending-trainer/Program.cs",
        "content": "using System;\nusing System.Threading;\nusing AstriaAscendingTrainer.Core;\nusing AstriaAscendingTrainer.Memory;\n\nnamespace AstriaAscendingTrainer\n{\n    /// <summary>\n    /// Entry point for the Astria Ascending trainer application.\n    /// Provides a console interface for toggling cheats.\n    /// </summary>\n    internal class Program\n    {\n        private static GameMemoryReader? _memoryReader;\n        private static GameCheatEngine? _cheatEngine;\n        private static bool _running = true;\n\n        static void Main(string[] args)\n        {\n            Console.Title = \"Astria Ascending Trainer v1.0\";\n            Console.WriteLine(\"Initializing trainer...\");\n\n            try\n            {\n                _memoryReader = new GameMemoryReader(\"AstriaAscending\");\n                _cheatEngine = new GameCheatEngine(_memoryReader);\n\n                if (!_memoryReader.IsProcessOpen)\n                {\n                    Console.WriteLine(\"Error: Astria Ascending process not found. Please start the game first.\");\n                    Console.WriteLine(\"Press any key to exit...\");\n                    Console.ReadKey();\n                    return;\n                }\n\n                Console.WriteLine(\"Process found. Trainer ready.\");\n                Console.WriteLine(\"Controls:\");\n                Console.WriteLine(\"  [1] Infinite HP\");\n                Console.WriteLine(\"  [2] Infinite MP\");\n                Console.WriteLine(\"  [3] Max Gold\");\n                Console.WriteLine(\"  [4] Max Experience\");\n                Console.WriteLine(\"  [5] Unlock All Skills\");\n                Console.WriteLine(\"  [0] Exit\");\n\n                while (_running)\n                {\n                    if (Console.KeyAvailable)\n                    {\n                        var key = Console.ReadKey(true).Key;\n                        HandleKeyPress(key);\n                    }\n                    Thread.Sleep(100);\n                }\n            }\n            catch (Exception ex)\n            {\n                Console.WriteLine($\"Fatal error: {ex.Message}\");\n                Console.WriteLine(\"Press any key to exit...\");\n                Console.ReadKey();\n            }\n        }\n\n        private static void HandleKeyPress(ConsoleKey key)\n        {\n            switch (key)\n            {\n                case ConsoleKey.D1:\n                    _cheatEngine?.ToggleInfiniteHP();\n                    Console.WriteLine($\"Infinite HP: {(_cheatEngine?.IsInfiniteHPActive == true ? \"ON\" : \"OFF\")}\");\n                    break;\n                case ConsoleKey.D2:\n                    _cheatEngine?.ToggleInfiniteMP();\n                    Console.WriteLine($\"Infinite MP: {(_cheatEngine?.IsInfiniteMPActive == true ? \"ON\" : \"OFF\")}\");\n                    break;\n                case ConsoleKey.D3:\n                    _cheatEngine?.SetMaxGold();\n                    Console.WriteLine(\"Gold set to maximum.\");\n                    break;\n                case ConsoleKey.D4:\n                    _cheatEngine?.SetMaxExperience();\n                    Console.WriteLine(\"Experience set to maximum.\");\n                    break;\n                case ConsoleKey.D5:\n                    _cheatEngine?.UnlockAllSkills();\n                    Console.WriteLine(\"All skills unlocked.\");\n                    break;\n                case ConsoleKey.D0:\n                    _running = false;\n                    Console.WriteLine(\"Shutting down trainer...\");\n                    break;\n            }\n        }\n    }\n}"
    },
