        "path": "astria-ascending-trainer/Core/GameCheatEngine.cs",
        "content": "using System;\nusing System.Collections.Generic;\nusing AstriaAscendingTrainer.Memory;\n\nnamespace AstriaAscendingTrainer.Core\n{\n    /// <summary>\n    /// Core cheat engine that manages cheat states and applies memory patches.\n    /// Uses known memory offsets for Astria Ascending (version 1.0.3).\n    /// </summary>\n    public class GameCheatEngine\n    {\n        private readonly GameMemoryReader _memoryReader;\n        private bool _infiniteHpActive;\n        private bool _infiniteMpActive;\n\n        // Memory offsets (example values - would need actual reverse engineering)\n        private const int HealthOffset = 0x00A1B2C0;\n        private const int ManaOffset = 0x00A1B2C4;\n        private const int GoldOffset = 0x00A1B2D0;\n        private const int ExperienceOffset = 0x00A1B2D8;\n        private const int SkillArrayOffset = 0x00A1B300;\n\n        /// <summary>\n        /// Whether infinite HP is currently active.\n        /// </summary>\n        public bool IsInfiniteHPActive => _infiniteHpActive;\n\n        /// <summary>\n        /// Whether infinite MP is currently active.\n        /// </summary>\n        public bool IsInfiniteMPActive => _infiniteMpActive;\n\n        public GameCheatEngine(GameMemoryReader memoryReader)\n        {\n            _memoryReader = memoryReader ?? throw new ArgumentNullException(nameof(memoryReader));\n        }\n\n        /// <summary>\n        /// Toggles infinite health by continuously writing max HP value.\n        /// </summary>\n        public void ToggleInfiniteHP()\n        {\n            _infiniteHpActive = !_infiniteHpActive;\n\n            if (_infiniteHpActive)\n            {\n                // Write a very high health value (99999) to prevent death\n                _memoryReader.WriteMemory(HealthOffset, BitConverter.GetBytes(99999));\n                Console.WriteLine(\"[Cheat] Infinite HP enabled.\");\n            }\n            else\n            {\n                Console.WriteLine(\"[Cheat] Infinite HP disabled.\");\n            }\n        }\n\n        /// <summary>\n        /// Toggles infinite mana by continuously writing max MP value.\n        /// </summary>\n        public void ToggleInfiniteMP()\n        {\n            _infiniteMpActive = !_infiniteMpActive;\n\n            if (_infiniteMpActive)\n            {\n                _memoryReader.WriteMemory(ManaOffset, BitConverter.GetBytes(9999));\n                Console.WriteLine(\"[Cheat] Infinite MP enabled.\");\n            }\n            else\n            {\n                Console.WriteLine(\"[Cheat] Infinite MP disabled.\");\n            }\n        }\n\n        /// <summary>\n        /// Sets the player's gold to the maximum possible value (999999).\n        /// </summary>\n        public void SetMaxGold()\n        {\n            _memoryReader.WriteMemory(GoldOffset, BitConverter.GetBytes(999999));\n            Console.WriteLine(\"[Cheat] Gold set to 999999.\");\n        }\n\n        /// <summary>\n        /// Sets the player's experience to a high value to trigger level-up.\n        /// </summary>\n        public void SetMaxExperience()\n        {\n            _memoryReader.WriteMemory(ExperienceOffset, BitConverter.GetBytes(99999));\n            Console.WriteLine(\"[Cheat] Experience set to 99999.\");\n        }\n\n        /// <summary>\n        /// Unlocks all skills by writing skill IDs to the skill array in memory.\n        /// Assumes skills are stored as a contiguous array of 32-bit integers.\n        /// </summary>\n        public void UnlockAllSkills()\n        {\n            // Simulate unlocking 20 skills (IDs 1-20)\n            var skillIds = new List<int>();\n            for (int i = 1; i <= 20; i++)\n            {\n                skillIds.Add(i);\n            }\n\n            byte[] skillData = new byte[skillIds.Count * 4];\n            Buffer.BlockCopy(skillIds.ToArray(), 0, skillData, 0, skillData.Length);\n\n            _memoryReader.WriteMemory(SkillArrayOffset, skillData);\n            Console.WriteLine(\"[Cheat] All 20 skills unlocked.\");\n        }\n    }\n}"
    },
