        "path": "astria-ascending-trainer/Memory/GameMemoryReader.cs",
        "content": "using System;\nusing System.Diagnostics;\nusing System.Runtime.InteropServices;\n\nnamespace AstriaAscendingTrainer.Memory\n{\n    /// <summary>\n    /// Provides low-level memory operations for reading/writing process memory.\n    /// Uses Windows API via P/Invoke for memory manipulation.\n    /// </summary>\n    public class GameMemoryReader : IDisposable\n    {\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern IntPtr OpenProcess(uint dwDesiredAccess, bool bInheritHandle, int dwProcessId);\n\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern bool CloseHandle(IntPtr hObject);\n\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern bool ReadProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int dwSize, out int lpNumberOfBytesRead);\n\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern bool WriteProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int dwSize, out int lpNumberOfBytesWritten);\n\n        private const uint ProcessAllAccess = 0x1F0FFF;\n        private const int BaseAddress = 0x400000; // Example base address\n\n        private IntPtr _processHandle;\n        private readonly int _processId;\n        private bool _disposed;\n\n        /// <summary>\n        /// Whether the target process is currently open and accessible.\n        /// </summary>\n        public bool IsProcessOpen => _processHandle != IntPtr.Zero;\n\n        /// <summary>\n        /// Initializes a new memory reader for the specified process name.\n        /// </summary>\n        /// <param name=\"processName\">The name of the target process (without extension).</param>\n        public GameMemoryReader(string processName)\n        {\n            Process[] processes = Process.GetProcessesByName(processName);\n            if (processes.Length == 0)\n            {\n                _processHandle = IntPtr.Zero;\n                _processId = -1;\n                return;\n            }\n\n            _processId = processes[0].Id;\n            _processHandle = OpenProcess(ProcessAllAccess, false, _processId);\n\n            if (_processHandle == IntPtr.Zero)\n            {\n                throw new InvalidOperationException($\"Failed to open process {processName} (PID: {_processId}). Error code: {Marshal.GetLastWin32Error()}\");\n            }\n        }\n\n        /// <summary>\n        /// Reads a block of memory from the target process.\n        /// </summary>\n        /// <param name=\"offset\">The offset from the base address.</param>\n        /// <param name=\"size\">Number of bytes to read.</param>\n        /// <returns>Byte array containing the read data.</returns>\n        public byte[] ReadMemory(int offset, int size)\n        {\n            if (_processHandle == IntPtr.Zero)\n                throw new InvalidOperationException(\"Process handle is not valid.\");\n\n            IntPtr address = IntPtr.Add(new IntPtr(BaseAddress), offset);\n            byte[] buffer = new byte[size];\n\n            if (!ReadProcessMemory(_processHandle, address, buffer, size, out int bytesRead))\n            {\n                throw new InvalidOperationException($\"Failed to read memory at offset 0x{offset:X}. Error code: {Marshal.GetLastWin32Error()}\");\n            }\n\n            if (bytesRead != size)\n            {\n                throw new InvalidOperationException($\"Read {bytesRead} bytes, but requested {size} bytes.\");\n            }\n\n            return buffer;\n        }\n\n        /// <summary>\n        /// Writes a block of memory to the target process.\n        /// </summary>\n        /// <param name=\"offset\">The offset from the base address.</param>\n        /// <param name=\"data\">Byte array containing the data to write.</param>\n        public void WriteMemory(int offset, byte[] data)\n        {\n            if (_processHandle == IntPtr.Zero)\n                throw new InvalidOperationException(\"Process handle is not valid.\");\n\n            IntPtr address = IntPtr.Add(new IntPtr(BaseAddress), offset);\n\n            if (!WriteProcessMemory(_processHandle, address, data, data.Length, out int bytesWritten))\n            {\n                throw new InvalidOperationException($\"Failed to write memory at offset 0x{offset:X}. Error code: {Marshal.GetLastWin32Error()}\");\n            }\n\n            if (bytesWritten != data.Length)\n            {\n                throw new InvalidOperationException($\"Wrote {bytesWritten} bytes, but attempted {data.Length} bytes.\");\n            }\n        }\n\n        /// <summary>\n        /// Releases the process handle.\n        /// </summary>\n        public void Dispose()\n        {\n            if (!_disposed && _processHandle != IntPtr.Zero)\n            {\n                CloseHandle(_processHandle);\n                _processHandle = IntPtr.Zero;\n                _disposed = true;\n            }\n\n            GC.SuppressFinalize(this);\n        }\n\n        ~GameMemoryReader()\n        {\n            Dispose();\n        }\n    }\n}"
    },
