        "path": "astria-ascending-trainer/Tests/GameCheatEngineTests.cs",
        "content": "using System;\nusing AstriaAscendingTrainer.Core;\nusing AstriaAscendingTrainer.Memory;\nusing Moq;\nusing Xunit;\n\nnamespace AstriaAscendingTrainer.Tests\n{\n    /// <summary>\n    /// Unit tests for the GameCheatEngine class.\n    /// Uses Moq to mock the GameMemoryReader dependency.\n    /// </summary>\n    public class GameCheatEngineTests\n    {\n        private readonly Mock<GameMemoryReader> _mockMemoryReader;\n        private readonly GameCheatEngine _cheatEngine;\n\n        public GameCheatEngineTests()\n        {\n            // Mock the GameMemoryReader with a dummy process name\n            _mockMemoryReader = new Mock<GameMemoryReader>(\"TestProcess\");\n            _cheatEngine = new GameCheatEngine(_mockMemoryReader.Object);\n        }\n\n        [Fact]\n        public void ToggleInfiniteHP_ShouldToggleState_WhenCalled()\n        {\n            // Arrange\n            bool initialState = _cheatEngine.IsInfiniteHPActive;\n\n            // Act\n            _cheatEngine.ToggleInfiniteHP();\n\n            // Assert\n            Assert.NotEqual(initialState, _cheatEngine.IsInfiniteHPActive);\n            Assert.True(_cheatEngine.IsInfiniteHPActive);\n\n            // Toggle back\n            _cheatEngine.ToggleInfiniteHP();\n            Assert.False(_cheatEngine.IsInfiniteHPActive);\n        }\n\n        [Fact]\n        public void ToggleInfiniteMP_ShouldToggleState_WhenCalled()\n        {\n            // Arrange\n            bool initialState = _cheatEngine.IsInfiniteMPActive;\n\n            // Act\n            _cheatEngine.ToggleInfiniteMP();\n\n            // Assert\n            Assert.NotEqual(initialState, _cheatEngine.IsInfiniteMPActive);\n            Assert.True(_cheatEngine.IsInfiniteMPActive);\n\n            // Toggle back\n            _cheatEngine.ToggleInfiniteMP();\n            Assert.False(_cheatEngine.IsInfiniteMPActive);\n        }\n\n        [Fact]\n        public void SetMaxGold_ShouldWriteExpectedValue_WhenCalled()\n        {\n            // Arrange\n            byte[] expectedData = BitConverter.GetBytes(999999);\n\n            // Act\n            _cheatEngine.SetMaxGold();\n\n            // Assert\n            _mockMemoryReader.Verify(m => m.WriteMemory(It.IsAny<int>(), It.Is<byte[]>(data =>\n                BitConverter.ToInt32(data, 0) == 999999)), Times.Once);\n        }\n\n        [Fact]\n        public void SetMaxExperience_ShouldWriteExpectedValue_WhenCalled()\n        {\n            // Arrange\n            byte[] expectedData = BitConverter.GetBytes(99999);\n\n            // Act\n            _cheatEngine.SetMaxExperience();\n\n            // Assert\n            _mockMemoryReader.Verify(m => m.WriteMemory(It.IsAny<int>(), It.Is<byte[]>(data =>\n                BitConverter.ToInt32(data, 0) == 99999)), Times.Once);
